<?php
namespace App\Support;
use App\Models\{User,Apprentice,OperationalFollowup as Followup};
use Illuminate\Support\Facades\DB;
use Illuminate\Support\Str;
class OperationalFollowups {
 public const STATES=['In progress','Waiting','Resolved'];
 public static function allowed(User $u,Apprentice $a,string $kind):bool {if(!$u->active||AccountLifecycle::blocked($u)||!StaffAttention::allowed($u)){return false;}if(LearningAccess::manager($u)){return true;}if(in_array($kind,['attendance','task','marking','action','progress','employer'],true)){return LearningAccess::tutor($u,$a);}return $a->tutor_id===$u->id&&$u->role==='tutor'||$a->mentor_id===$u->id&&StaffDuties::has($u,'mentor');}
 public static function fields(Followup $f):array {return $f->only(['id','request_token','apprentice_id','owner_id','source_key','source_kind','status','version','open_key']);}
 public static function intact(Followup $f):bool {try{return $f->details['fields']===self::fields($f);}catch(\Throwable){return false;}}
 public static function reasons(User $u):array {$p=StaffAttention::for($u);abort_if($p['scope_count']>1000,422,'Narrow/review staff caseload before opening this desk.');$out=[];foreach($p['rows']as$row){foreach($row['reasons']as$reason){$key=ReviewedImports::hash(['apprentice'=>$row['apprentice']->id,'reason'=>$reason]);$out[$key]=['apprentice'=>$row['apprentice'],'reason'=>$reason,'key'=>$key,'can_followup'=>self::allowed($u,$row['apprentice'],$reason['kind'])];}}return $out;}
 public static function visible(User $u,?string $search=null,string $state='all') {abort_unless(StaffAttention::allowed($u)&&!AccountLifecycle::blocked($u),403);$people=StaffAttention::people($u);$ids=$people->pluck('id');if(filled($search)){$ids=$people->filter(fn($a)=>mb_stripos($a->reference.' '.$a->first_name.' '.$a->last_name,trim($search))!==false)->pluck('id');}$q=Followup::whereIn('apprentice_id',$ids);if(!LearningAccess::manager($u)){$training=$u->role==='tutor'?Apprentice::whereIn('id',$ids)->where('tutor_id',$u->id)->pluck('id'):collect();$mentor=StaffDuties::has($u,'mentor')?Apprentice::whereIn('id',$ids)->where('mentor_id',$u->id)->pluck('id'):collect();$q->where(fn($q)=>$q->whereIn('apprentice_id',$training)->orWhere(fn($q)=>$q->whereIn('apprentice_id',$mentor)->whereNotIn('source_kind',['attendance','task','marking','action','progress','employer'])));}if($state!=='all'){$q->where('status',$state);}return $q->orderByDesc('updated_at')->limit(1001)->get()->filter(fn($f)=>self::allowed($u,Apprentice::findOrFail($f->apprentice_id),$f->source_kind));}
 public static function start(User $actor,int $auth,Apprentice $person,string $key,User $owner,string $token,string $due,string $reference):Followup {return DB::transaction(function()use($actor,$auth,$person,$key,$owner,$token,$due,$reference):Followup {User::whereIn('id',[$actor->id,$owner->id])->orderBy('id')->lockForUpdate()->get();$u=PortalOperations::actor($actor,$auth);$a=Apprentice::whereKey($person->id)->lockForUpdate()->firstOrFail();$o=User::findOrFail($owner->id);$reason=self::reasons($u)[$key]??null;abort_unless($reason&&$reason['apprentice']->id===$a->id&&self::allowed($u,$a,$reason['reason']['kind'])&&self::allowed($o,$a,$reason['reason']['kind']),403);if(!Str::isUuid($token)||!PortalOperations::reference($reference)){CentrePlanning::fail('Use a fresh source-linked request and safe operational reference.');}validator(['due'=>$due],['due'=>'required|date_format:Y-m-d|after_or_equal:today'])->validate();$payload=['due'=>$due,'reference'=>$reference];$old=Followup::where('request_token',$token)->first();if($old){if(self::intact($old)&&$old->details['history'][0]['by']===$u->id&&$old->source_key===$key&&$old->owner_id===$o->id&&$old->details['initial']===$payload){return $old;}CentrePlanning::fail('Request already used for different follow-up work.');}$open=ReviewedImports::hash([$a->id,$key]);if(Followup::where('open_key',$open)->lockForUpdate()->exists()){CentrePlanning::fail('An open follow-up already exists for this exact source flag.');}$f=new Followup(['id'=>(string)Str::uuid(),'request_token'=>$token,'apprentice_id'=>$a->id,'owner_id'=>$o->id,'source_key'=>$key,'source_kind'=>$reason['reason']['kind'],'status'=>'In progress','version'=>1,'open_key'=>$open]);$f->details=['fields'=>self::fields($f),'source'=>$reason['reason'],'initial'=>$payload,'due'=>$due,'history'=>[['by'=>$u->id,'reference'=>$reference,'at'=>now()->toIso8601String(),'status'=>'In progress']]];$f->save();PortalOperations::event($u,'followup',$f->id,'followup_started',['apprentice'=>$a->id,'owner'=>$o->id,'source_key'=>$key]);return $f;},3);}
 public static function update(User $actor,int $auth,Followup $record,int $version,string $status,User $owner,string $due,string $reference):void {DB::transaction(function()use($actor,$auth,$record,$version,$status,$owner,$due,$reference):void {User::whereIn('id',[$actor->id,$owner->id])->orderBy('id')->lockForUpdate()->get();$u=PortalOperations::actor($actor,$auth);$f=Followup::whereKey($record->id)->lockForUpdate()->firstOrFail();$a=Apprentice::whereKey($f->apprentice_id)->lockForUpdate()->firstOrFail();$o=User::findOrFail($owner->id);abort_unless(self::allowed($u,$a,$f->source_kind)&&self::allowed($o,$a,$f->source_kind)&&(LearningAccess::manager($u)||$f->owner_id===$u->id),403);abort_if(!LearningAccess::manager($u)&&$o->id!==$u->id,403);if(!self::intact($f)||$f->version!==$version||$f->status==='Resolved'||!in_array($status,self::STATES,true)||!PortalOperations::reference($reference)){CentrePlanning::fail('Use the current open follow-up and a safe update reference.');}validator(['due'=>$due],['due'=>'required|date_format:Y-m-d'])->validate();$before=self::fields($f);$d=$f->details;$f->version++;$f->status=$status;$f->owner_id=$o->id;if($status==='Resolved'){$f->open_key=null;}$d['due']=$due;$d['history'][]=['before'=>$before,'status'=>$status,'owner'=>$o->id,'by'=>$u->id,'reference'=>$reference,'at'=>now()->toIso8601String()];$d['fields']=self::fields($f);$f->details=$d;$f->save();PortalOperations::event($u,'followup',$f->id,'followup_updated',['before'=>$before,'after'=>self::fields($f),'source_workflow_unchanged'=>true]);},3);}
}
